WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY shipping_fee NULLS FIRST, id) AS rank_in_group FROM orders) t WHERE rank_in_group = 1) SELECT customer_id, COUNT(CASE WHEN channel = 'partner' THEN 1 END) AS partner_count, CORR(amount, shipping_fee) AS corr_amount_shipping_fee FROM ranked GROUP BY customer_id ORDER BY partner_count NULLS FIRST;
